 for(let i=0;i<=4;i++){let value=ymin+(ymax-ymin)*i/4,y=py(value);svg+=`<path d="M${left} ${y} H${width-right}" stroke="#30485c"/><text x="${left-10}" y="${y+4}" text-anchor="end" fill="#aebfd4" font-size="13">${nf(value,0)}</text>`;}
