function renderFlightTable(){if(!flightResult?.descent)return;const rows=selectedRows(),max=Math.ceil(rows.length/25)-1;tablePage=Math.min(tablePage,max);flightEl('flightPrev').disabled=tablePage===0;flightEl('flightNext').disabled=tablePage>=max;
 flightEl('descentPlots').innerHTML=linePlot(rows,[{key:'alt',label:'Altitude above assumed flat datum',color:'#72dfca'}],{title:'Descent altitude · time from carrier extraction',unit:'m'})+linePlot(rows,[{key:'v',label:'Total ground-relative speed',color:'#ffcd82'},{key:'verticalSpeed',label:'Downward velocity',color:'#72dfca'}],{title:'Descent velocity · time from carrier extraction',unit:'m/s'});
 flightEl('flightTableLabel').textContent=`Rows ${tablePage*25+1}–${Math.min(rows.length,(tablePage+1)*25)} of ${rows.length}. Every integration step is available; nominal step 0.25 s, shortened at release/ground events. Probe time uses the same carrier-extraction origin.`;
 flightEl('flightTable').innerHTML='<table><thead><tr><th>Time (s)</th><th>Altitude (m)</th><th>Total speed (m/s)</th><th>Down (m/s)</th><th>Horizontal (m/s)</th><th>Mass (kg)</th></tr></thead><tbody>'+rows.slice(tablePage*25,(tablePage+1)*25).map(r=>`<tr><td>${nf(r.t,4)}</td><td>${nf(r.alt,3)}</td><td>${nf(r.v,3)}</td><td>${nf(r.verticalSpeed,3)}</td><td>${nf(r.vx,3)}</td><td>${nf(r.mass,2)}</td></tr>`).join('')+'</tbody></table>';
}
function downloadFlight(data,name,type){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function exportFlightCSV(){const f=flightResult;if(!f?.descent)return;let lines=['configuration,entity,time_from_extraction_s,mission_time_s,altitude_m,total_ground_speed_m_s,downward_speed_m_s,horizontal_speed_m_s,mass_kg'];for(const e of [{name:'carrier',rows:f.descent.rows},...f.descent.probes.map(p=>({name:'probe_'+p.id,rows:p.rows}))])for(const r of e.rows)lines.push([flightConfig,e.name,r.t,f.times.descentStart+r.t,r.alt,r.v,r.verticalSpeed,r.vx,r.mass].join(','));downloadFlight(lines.join('\n'),'FREYA_'+flightConfig+'_all_descent_steps.csv','text/csv');}
function flightAnimate(now){if(flightFrame===null)flightFrame=now;let dt=Math.min(.2,(now-flightFrame)/1000);flightFrame=now;if(flightPlaying&&flightResult?.times){flightPosition=Math.min(1000,flightPosition+dt*14);if(flightPosition>=1000)flightPlaying=false;renderPhysical();}requestAnimationFrame(flightAnimate);}
